    m8_add_model("chest_demon", 3.5, 5.5, 0.0, 45, "idle", 1.0);  // Cofre de Reliquias
    m8_add_model("md3_pillar", 5.5, 5.5, 0.0, 0, "idle", 1.2);    // Columna gótica
    m8_add_model("md3_pillar", 9.5, 5.5, 0.0, 0, "idle", 1.2);    // Columna gótica

